w("lib/site.ts", """export const SITE_NAME = \"Drew's News\";\nexport const SITE_ORIGIN = (process.env.NEXT_PUBLIC_SITE_URL || \"https://drewsnews.com\").replace(/\\/$/, \"\");\nexport const SECTIONS = [\"ai\", \"science\", \"environment\", \"horoscope\", \"politics\", \"humor\"] as const;\nexport type SectionSlug = (typeof SECTIONS)[number];\nexport const SIGNS = [\"aries\",\"taurus\",\"gemini\",\"cancer\",\"leo\",\"virgo\",\"libra\",\"scorpio\",\"sagittarius\",\"capricorn\",\"aquarius\",\"pisces\"] as const;\nexport type SignSlug = (typeof SIGNS)[number];\nexport const SECTION_LABEL: Record<SectionSlug, string> = { ai: \"AI\", science: \"Science\", environment: \"Environment\", horoscope: \"Horoscope\", politics: \"Politics\", humor: \"Humor\" };\nexport const SIGN_LABEL: Record<SignSlug, string> = { aries: \"Aries\", taurus: \"Taurus\", gemini: \"Gemini\", cancer: \"Cancer\", leo: \"Leo\", virgo: \"Virgo\", libra: \"Libra\", scorpio: \"Scorpio\", sagittarius: \"Sagittarius\", capricorn: \"Capricorn\", aquarius: \"Aquarius\", pisces: \"Pisces\" };\nexport function isSection(v: string): v is SectionSlug { return (SECTIONS as readonly string[]).includes(v); }\nexport function isSign(v: string): v is SignSlug { return (SIGNS as readonly string[]).includes(v); }\nexport function absUrl(path: string): string { const p = path.startsWith(\"/\") ? path : `/${path}`; return `${SITE_ORIGIN}${p.endsWith(\"/\") ? p : `${p}/`}`; }\n""")
