signs = {"aries": {"sign":"aries","headline":"Aries: a clean start beats a loud one","dek":"Mars weather favors a short list and a finished errand, not a new crusade.","lede":"Today favors the errand you can finish before lunch, not the manifesto you keep rewriting. Aries energy is sharp when it is brief. Say the hard sentence once, then leave room for someone else to answer. The sky is not asking for a spectacle.","body":["Name the actual deadline.","Walk without headphones tonight."],"publishedAt":"2026-08-22T07:00:00.000Z","updatedAt":"2026-08-22T07:00:00.000Z"}, "taurus": {"sign":"taurus","headline":"Taurus: keep the table, change the seating","dek":"Comfort is a tool today if you share it, not a bunker if you hoard it.","lede":"Taurus does well when the room is steady and the chairs can move. Keep the table you trust, but let a new person sit closer than usual. Money talk stays calm if it stays specific. The day rewards maintenance more than a purchase you cannot name.","body":["Finish the postponed household task.","Wait one hour before sending a heavy message."],"publishedAt":"2026-08-22T07:00:00.000Z","updatedAt":"2026-08-22T07:00:00.000Z"}}
w("lib/horoscopes.ts", "import type { DailySign } from \"./types\";\nimport type { SignSlug } from \"./site\";\n\nexport const DAILY_SIGNS: Partial<Record<SignSlug, DailySign>> = " + json.dumps(signs, indent=2) + ";\n")
w("lib/content.ts", """import { STORIES } from \"./stories\";\nimport { DAILY_SIGNS } from \"./horoscopes\";\nimport type { Story, DailySign } from \"./types\";\nimport { SIGN_LABEL, isSection, isSign, type SectionSlug, type SignSlug } from \"./site\";\nexport function getPublishedStories(): Story[] {\n  return STORIES.filter((s) => s.status === \"published\").sort((a, b) => (a.publishedAt < b.publishedAt ? 1 : -1));\n}\nexport function getStoriesBySection(section: SectionSlug): Story[] {\n  return getPublishedStories().filter((s) => s.section === section).slice(0, 24);\n}\nexport function storyPath(story: Story): string {\n  const d = new Date(story.publishedAt);\n  return `/${story.section}/${d.getUTCFullYear()}/${String(d.getUTCMonth() + 1).padStart(2, \"0\")}/${story.slug}/`;\n}\nexport function getStory(section: string, year: string, month: string, slug: string): Story | undefined {\n  if (!isSection(section)) return undefined;\n  const story = STORIES.find((s) => s.section === section && s.slug === slug && s.status === \"published\");\n  if (!story) return undefined;\n  const d = new Date(story.publishedAt);\n  if (String(d.getUTCFullYear()) !== year || String(d.getUTCMonth() + 1).padStart(2, \"0\") !== month) return undefined;\n  return story;\n}\nexport function getRelated(story: Story, n = 2): Story[] {\n  const pool = getPublishedStories().filter((s) => s.slug !== story.slug);\n  return [...pool.filter((s) => s.section === story.section), ...pool.filter((s) => s.section !== story.section)].slice(0, n);\n}\nfunction fallbackSign(sign: SignSlug): DailySign {\n  const label = SIGN_LABEL[sign];\n  return { sign, headline: `${label}: hold the line and notice the weather`, dek: `A steady ${label} day rewards patience over a grand gesture.`, lede: `${label} readers get a quiet chart today: one clear task, one honest reply, and no need to announce either. The sky is asking for follow-through, not a new identity. Keep the phone in another room for an hour and the rest of the advice will fit.`, body: [\"A small repair counts as the main transit.\", \"Give a real window if someone asks for time.\"], publishedAt: \"2026-08-22T07:00:00.000Z\", updatedAt: \"2026-08-22T07:00:00.000Z\" };\n}\nexport function getDailySign(sign: string): DailySign | undefined {\n  if (!isSign(sign)) return undefined;\n  return DAILY_SIGNS[sign] ?? fallbackSign(sign);\n}\nexport function allPublicStoryParams() {\n  return getPublishedStories().map((s) => {\n    const d = new Date(s.publishedAt);\n    return { section: s.section, year: String(d.getUTCFullYear()), month: String(d.getUTCMonth() + 1).padStart(2, \"0\"), slug: s.slug };\n  });\n}\n""")
w("lib/seo.ts", """import { absUrl, SITE_NAME, SITE_ORIGIN, SECTION_LABEL, type SectionSlug } from \"./site\";\nconst org = { \"@type\": \"NewsMediaOrganization\", \"@id\": `${SITE_ORIGIN}/#org`, name: SITE_NAME, url: absUrl(\"/\") };\nconst website = { \"@type\": \"WebSite\", \"@id\": `${SITE_ORIGIN}/#website`, name: SITE_NAME, url: absUrl(\"/\"), publisher: { \"@id\": `${SITE_ORIGIN}/#org` } };\nexport function orgAndSiteLd() { return [org, website]; }\nexport function collectionLd(name: string, url: string, items: { name: string; url: string }[]) {\n  return { \"@context\": \"https://schema.org\", \"@graph\": [...orgAndSiteLd(), { \"@type\": \"CollectionPage\", name, url, isPartOf: { \"@id\": `${SITE_ORIGIN}/#website` }, mainEntity: { \"@type\": \"ItemList\", itemListElement: items.map((item, i) => ({ \"@type\": \"ListItem\", position: i + 1, name: item.name, url: item.url })) } }] };\n}\nexport function newsArticleLd(o: { headline: string; dek: string; url: string; image: string; publishedAt: string; updatedAt: string; section?: string }) {\n  return { \"@context\": \"https://schema.org\", \"@graph\": [...orgAndSiteLd(), { \"@type\": \"NewsArticle\", headline: o.headline, description: o.dek, url: o.url, image: [o.image], datePublished: o.publishedAt, dateModified: o.updatedAt, articleSection: o.section, author: { \"@id\": `${SITE_ORIGIN}/#org` }, publisher: { \"@id\": `${SITE_ORIGIN}/#org` }, mainEntityOfPage: o.url }] };\n}\nexport function clip(s: string, min = 150, max = 160): string {\n  const t = s.replace(/\\s+/g, \" \").trim();\n  if (t.length <= max && t.length >= min) return t;\n  if (t.length > max) { const cut = t.slice(0, max - 1); const i = cut.lastIndexOf(\" \"); return (i > 120 ? cut.slice(0, i) : cut).trimEnd(); }\n  return (t + \" Coverage from Drew's News, an independent newsroom.\").slice(0, max);\n}\nexport function sectionTitle(section: SectionSlug): string { return `${SECTION_LABEL[section]} news | ${SITE_NAME}`; }\n""")
w("tailwind.config.ts", """import type { Config } from \"tailwindcss\";\nconst config: Config = { content: [\"./app/**/*.{js,ts,jsx,tsx,mdx}\", \"./components/**/*.{js,ts,jsx,tsx,mdx}\"], theme: { extend: { colors: { forest: \"#0B6E4F\", ink: \"#0A2E24\", paper: \"#FFFFFF\", mist: \"#F4F8F6\", muted: \"#4A635A\", line: \"#D7E4DE\" }, fontFamily: { serif: [\"Georgia\", \"serif\"], sans: [\"Helvetica Neue\", \"Arial\", \"sans-serif\"] } } }, plugins: [] };\nexport default config;\n""")
w("app/globals.css", """@tailwind base;\n@tailwind components;\n@tailwind utilities;\nhtml { color-scheme: light; }\nbody { @apply bg-paper text-ink antialiased font-sans; }\n""")
w("components/Masthead.tsx", """import Link from \"next/link\";\nimport { SITE_NAME } from \"@/lib/site\";\nexport function Masthead() {\n  return (<header className=\"border-b border-line bg-paper\"><div className=\"mx-auto max-w-5xl px-4 py-5\"><Link href=\"/\" className=\"font-serif text-3xl font-semibold text-forest\">{SITE_NAME}</Link></div></header>);\n}\n""")
w("components/SectionNav.tsx", """import Link from \"next/link\";\nimport { SECTIONS, SECTION_LABEL } from \"@/lib/site\";\nexport function SectionNav() {\n  return (<nav className=\"border-b border-line bg-mist\" aria-label=\"Sections\"><ul className=\"mx-auto flex max-w-5xl flex-wrap gap-x-5 gap-y-2 px-4 py-3 text-sm font-medium\">{SECTIONS.map((s) => (<li key={s}><Link href={`/${s}/`} className=\"text-ink hover:text-forest\">{SECTION_LABEL[s]}</Link></li>))}</ul></nav>);\n}\n""")
w("components/Footer.tsx", """import Link from \"next/link\";\nimport { SITE_NAME } from \"@/lib/site\";\nexport function Footer() {\n  return (<footer className=\"mt-16 border-t border-line bg-mist\"><div className=\"mx-auto max-w-5xl px-4 py-8 text-sm text-muted\"><p>{SITE_NAME} is an independent newsroom.</p><p className=\"mt-2\"><Link href=\"/\" className=\"text-forest underline\">Home</Link></p></div></footer>);\n}\n""")
w("components/JsonLd.tsx", """export function JsonLd({ data }: { data: unknown }) {\n  return <script type=\"application/ld+json\" dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }} />;\n}\n""")
w("components/StoryCard.tsx", """import Link from \"next/link\";\nimport { SECTION_LABEL } from \"@/lib/site\";\nimport { storyPath } from \"@/lib/content\";\nimport type { Story } from \"@/lib/types\";\nexport function StoryCard({ story }: { story: Story }) {\n  return (<article className=\"border-b border-line py-5\"><p className=\"text-xs font-semibold uppercase tracking-wider text-forest\">{SECTION_LABEL[story.section]}{story.section === \"humor\" ? \" · SATIRE\" : \"\"}</p><h2 className=\"mt-1 font-serif text-2xl text-ink\"><Link href={storyPath(story)} className=\"hover:text-forest\">{story.headline}</Link></h2><p className=\"mt-2 text-muted\">{story.dek}</p><p className=\"mt-2 text-sm text-muted\">{story.byline} · {story.desk}</p></article>);\n}\n""")
w("components/StoryGrid.tsx", """import { StoryCard } from \"./StoryCard\";\nimport type { Story } from \"@/lib/types\";\nexport function StoryGrid({ stories }: { stories: Story[] }) {\n  return <div>{stories.map((story) => <StoryCard key={story.slug} story={story} />)}</div>;\n}\n""")
w("components/Timestamps.tsx", """export function Timestamps({ publishedAt, updatedAt }: { publishedAt: string; updatedAt: string }) {\n  return (<p className=\"text-sm text-muted\">Published <time dateTime={publishedAt}>{publishedAt}</time>{publishedAt !== updatedAt && <> · Updated <time dateTime={updatedAt}>{updatedAt}</time></>}</p>);\n}\n""")
w("app/layout.tsx", """import type { Metadata } from \"next\";\nimport { Footer } from \"@/components/Footer\";\nimport { Masthead } from \"@/components/Masthead\";\nimport { SectionNav } from \"@/components/SectionNav\";\nimport { SITE_NAME, SITE_ORIGIN, absUrl } from \"@/lib/site\";\nimport { clip } from \"@/lib/seo\";\nimport \"./globals.css\";\nconst description = clip(\"Independent coverage of AI, science, environment, politics, daily horoscopes, and satire from Drew's News.\");\nexport const metadata: Metadata = {\n  metadataBase: new URL(SITE_ORIGIN),\n  title: { default: `${SITE_NAME} | AI, Science, Environment, Politics`, template: `%s | ${SITE_NAME}` },\n  description,\n  robots: { index: true, follow: true },\n  alternates: { canonical: absUrl(\"/\") },\n  openGraph: { type: \"website\", siteName: SITE_NAME, title: `${SITE_NAME} | AI, Science, Environment, Politics`, description, url: absUrl(\"/\"), images: [{ url: \"/og/default.png\", width: 1200, height: 630, alt: SITE_NAME }] },\n  twitter: { card: \"summary_large_image\", title: `${SITE_NAME} | AI, Science, Environment, Politics`, description, images: [\"/og/default.png\"] },\n};\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (<html lang=\"en\"><body className=\"min-h-screen flex flex-col\"><Masthead /><SectionNav /><div className=\"flex-1\">{children}</div><Footer /></body></html>);\n}\n""")
w("app/page.tsx", """import type { Metadata } from \"next\";\nimport { getPublishedStories, storyPath } from \"@/lib/content\";\nimport { StoryGrid } from \"@/components/StoryGrid\";\nimport { JsonLd } from \"@/components/JsonLd\";\nimport { collectionLd, clip } from \"@/lib/seo\";\nimport { SITE_NAME, absUrl } from \"@/lib/site\";\nconst title = `${SITE_NAME} | AI, Science, Environment, Politics`;\nconst description = clip(\"Headlines in AI, science, environment, and politics, plus daily horoscopes and satire. Independent reporting from Drew's News.\");\nexport const metadata: Metadata = { title: { absolute: title }, description, robots: { index: true, follow: true }, alternates: { canonical: absUrl(\"/\") }, openGraph: { type: \"website\", siteName: SITE_NAME, title, description, url: absUrl(\"/\"), images: [{ url: \"/og/default.png\", width: 1200, height: 630 }] }, twitter: { card: \"summary_large_image\", title, description, images: [\"/og/default.png\"] } };\nexport default function HomePage() {\n  const stories = getPublishedStories();\n  const ld = collectionLd(title, absUrl(\"/\"), stories.map((s) => ({ name: s.headline, url: absUrl(storyPath(s)) })));\n  return (<main className=\"mx-auto max-w-5xl px-4 py-10\"><JsonLd data={ld} /><h1 className=\"font-serif text-4xl text-ink\">{SITE_NAME}</h1><p className=\"mt-3 max-w-2xl text-lg text-muted\">Independent coverage of AI, science, environment, politics, horoscopes, and humor.</p><section className=\"mt-10\" aria-label=\"Latest stories\"><StoryGrid stories={stories} /></section></main>);\n}\n""")
w("app/[section]/page.tsx", """import type { Metadata } from \"next\";\nimport { notFound } from \"next/navigation\";\nimport { getStoriesBySection, storyPath } from \"@/lib/content\";\nimport { StoryGrid } from \"@/components/StoryGrid\";\nimport { JsonLd } from \"@/components/JsonLd\";\nimport { collectionLd, clip, sectionTitle } from \"@/lib/seo\";\nimport { SECTION_LABEL, SECTIONS, SITE_NAME, absUrl, isSection, type SectionSlug } from \"@/lib/site\";\nexport function generateStaticParams() { return SECTIONS.map((section) => ({ section })); }\nexport async function generateMetadata({ params }: { params: Promise<{ section: string }> }): Promise<Metadata> {\n  const { section } = await params;\n  if (!isSection(section)) return {};\n  const title = sectionTitle(section);\n  const description = clip(`${SECTION_LABEL[section]} news and latest published stories from Drew's News, an independent digital newsroom.`);\n  const url = absUrl(`/${section}/`);\n  return { title: { absolute: title }, description, robots: { index: true, follow: true }, alternates: { canonical: url }, openGraph: { type: \"website\", siteName: SITE_NAME, title, description, url, images: [{ url: \"/og/default.png\", width: 1200, height: 630 }] }, twitter: { card: \"summary_large_image\", title, description, images: [\"/og/default.png\"] } };\n}\nexport default async function SectionPage({ params }: { params: Promise<{ section: string }> }) {\n  const { section } = await params;\n  if (!isSection(section)) notFound();\n  const stories = getStoriesBySection(section as SectionSlug);\n  const title = sectionTitle(section);\n  const url = absUrl(`/${section}/`);\n  const ld = collectionLd(title, url, stories.map((s) => ({ name: s.headline, url: absUrl(storyPath(s)) })));\n  return (<main className=\"mx-auto max-w-5xl px-4 py-10\"><JsonLd data={ld} /><p className=\"text-xs font-semibold uppercase tracking-wider text-forest\">Section</p><h1 className=\"mt-2 font-serif text-4xl text-ink\">{SECTION_LABEL[section]}</h1><p className=\"mt-3 text-lg text-muted\">Latest published {SECTION_LABEL[section].toLowerCase()} stories.</p><section className=\"mt-8\" aria-label=\"Latest in section\">{stories.length === 0 ? <p className=\"text-muted\">No published stories yet.</p> : <StoryGrid stories={stories} />}</section></main>);\n}\n""")
w("app/[section]/[year]/[month]/[slug]/page.tsx", """import type { Metadata } from \"next\";\nimport Image from \"next/image\";\nimport Link from \"next/link\";\nimport { notFound } from \"next/navigation\";\nimport { allPublicStoryParams, getRelated, getStory, storyPath } from \"@/lib/content\";\nimport { JsonLd } from \"@/components/JsonLd\";\nimport { Timestamps } from \"@/components/Timestamps\";\nimport { newsArticleLd, clip } from \"@/lib/seo\";\nimport { SECTION_LABEL, SITE_NAME, SITE_ORIGIN, absUrl, isSection } from \"@/lib/site\";\nexport function generateStaticParams() { return allPublicStoryParams(); }\nexport async function generateMetadata({ params }: { params: Promise<{ section: string; year: string; month: string; slug: string }> }): Promise<Metadata> {\n  const { section, year, month, slug } = await params;\n  const story = getStory(section, year, month, slug);\n  if (!story) return { robots: { index: false, follow: false } };\n  const title = `${story.headline} | ${SITE_NAME}`;\n  const description = clip(`${story.dek} ${story.lede}`);\n  const url = absUrl(storyPath(story));\n  return { title: { absolute: title }, description, robots: { index: true, follow: true }, alternates: { canonical: url }, openGraph: { type: \"article\", siteName: SITE_NAME, title, description, url, images: [{ url: story.hero.src, width: 1200, height: 630, alt: story.hero.alt }], publishedTime: story.publishedAt, modifiedTime: story.updatedAt, section: SECTION_LABEL[story.section] }, twitter: { card: \"summary_large_image\", title, description, images: [story.hero.src] }, other: { \"article:published_time\": story.publishedAt, \"article:modified_time\": story.updatedAt, \"article:section\": SECTION_LABEL[story.section] } };\n}\nexport default async function StoryPage({ params }: { params: Promise<{ section: string; year: string; month: string; slug: string }> }) {\n  const { section, year, month, slug } = await params;\n  if (!isSection(section) || !/^\\\\d{4}$/.test(year)) notFound();\n  const story = getStory(section, year, month, slug);\n  if (!story) notFound();\n  const related = getRelated(story, 2);\n  const url = absUrl(storyPath(story));\n  const image = `${SITE_ORIGIN}${story.hero.src}`;\n  const ld = newsArticleLd({ headline: story.headline, dek: story.dek, url, image, publishedAt: story.publishedAt, updatedAt: story.updatedAt, section: SECTION_LABEL[story.section] });\n  return (<main className=\"mx-auto max-w-3xl px-4 py-10\"><JsonLd data={ld} /><article><p className=\"text-xs font-semibold uppercase tracking-wider text-forest\">{SECTION_LABEL[story.section]}{story.section === \"humor\" ? \" · SATIRE\" : \"\"}</p><h1 className=\"mt-2 font-serif text-4xl leading-tight text-ink\">{story.headline}</h1><p className=\"mt-4 text-xl text-muted\">{story.dek}</p><p className=\"mt-4 text-sm text-ink\">{story.byline} · {story.desk}</p><Timestamps publishedAt={story.publishedAt} updatedAt={story.updatedAt} /><div className=\"relative my-6 aspect-[1200/630] w-full overflow-hidden border border-line bg-mist\"><Image src={story.hero.src} alt={story.hero.alt} fill className=\"object-cover\" priority /></div><p className=\"text-lg leading-8 text-ink\">{story.lede}</p>{story.comic && (<figure className=\"my-8 border border-line bg-mist p-3\"><Image src={story.comic.src} alt={story.comic.caption} width={900} height={520} className=\"h-auto w-full\" /><figcaption className=\"mt-2 text-sm text-muted\">{story.comic.caption}</figcaption></figure>)}<div className=\"mt-6 space-y-4 text-lg leading-8\">{story.body.map((p, i) => <p key={i}>{p}</p>)}</div><p className=\"mt-8 text-sm\"><Link href={`/${story.section}/`} className=\"text-forest underline\">More {SECTION_LABEL[story.section]}</Link></p>{related.length > 0 && (<aside className=\"mt-10 border-t border-line pt-6\"><h2 className=\"font-serif text-2xl\">Related</h2><ul className=\"mt-3 list-disc space-y-2 pl-5\">{related.map((r) => <li key={r.slug}><Link href={storyPath(r)} className=\"text-forest underline\">{r.headline}</Link></li>)}</ul></aside>)}</article></main>);\n}\n""")
w("app/horoscope/[sign]/page.tsx", """import type { Metadata } from \"next\";\nimport { notFound } from \"next/navigation\";\nimport { getDailySign } from \"@/lib/content\";\nimport { JsonLd } from \"@/components/JsonLd\";\nimport { Timestamps } from \"@/components/Timestamps\";\nimport { newsArticleLd, clip } from \"@/lib/seo\";\nimport { SIGN_LABEL, SIGNS, SITE_NAME, SITE_ORIGIN, absUrl, isSign } from \"@/lib/site\";\nexport function generateStaticParams() { return SIGNS.map((sign) => ({ sign })); }\nexport async function generateMetadata({ params }: { params: Promise<{ sign: string }> }): Promise<Metadata> {\n  const { sign } = await params;\n  if (!isSign(sign)) return { robots: { index: false, follow: false } };\n  const item = getDailySign(sign)!;\n  const title = `${SIGN_LABEL[sign]} horoscope today | ${SITE_NAME}`;\n  const description = clip(`${item.dek} ${item.lede}`);\n  const url = absUrl(`/horoscope/${sign}/`);\n  return { title: { absolute: title }, description, robots: { index: true, follow: true }, alternates: { canonical: url }, openGraph: { type: \"article\", siteName: SITE_NAME, title, description, url, images: [{ url: \"/og/default.png\", width: 1200, height: 630 }], publishedTime: item.publishedAt, modifiedTime: item.updatedAt, section: \"Horoscope\" }, twitter: { card: \"summary_large_image\", title, description, images: [\"/og/default.png\"] }, other: { \"article:published_time\": item.publishedAt, \"article:modified_time\": item.updatedAt, \"article:section\": \"Horoscope\" } };\n}\nexport default async function SignPage({ params }: { params: Promise<{ sign: string }> }) {\n  const { sign } = await params;\n  if (!isSign(sign)) notFound();\n  const item = getDailySign(sign);\n  if (!item) notFound();\n  const url = absUrl(`/horoscope/${sign}/`);\n  const ld = newsArticleLd({ headline: item.headline, dek: item.dek, url, image: `${SITE_ORIGIN}/og/default.png`, publishedAt: item.publishedAt, updatedAt: item.updatedAt, section: \"Horoscope\" });\n  return (<main className=\"mx-auto max-w-3xl px-4 py-10\"><JsonLd data={ld} /><article><p className=\"text-xs font-semibold uppercase tracking-wider text-forest\">Horoscope</p><h1 className=\"mt-2 font-serif text-4xl text-ink\">{item.headline}</h1><p className=\"mt-4 text-xl text-muted\">{item.dek}</p><p className=\"mt-4 text-sm text-ink\">Horoscope Desk</p><Timestamps publishedAt={item.publishedAt} updatedAt={item.updatedAt} /><p className=\"mt-6 text-lg leading-8 text-ink\">{item.lede}</p><div className=\"mt-6 space-y-4 text-lg leading-8\">{item.body.map((p, i) => <p key={i}>{p}</p>)}</div></article></main>);\n}\n""")
w("app/sitemap.ts", """import type { MetadataRoute } from \"next\";\nimport { allPublicStoryParams, getPublishedStories, getDailySign, storyPath } from \"./../lib/content\";\nimport { SECTIONS, SIGNS, SITE_ORIGIN, absUrl } from \"./../lib/site\";\nexport default function sitemap(): MetadataRoute.Sitemap {\n  const stories = getPublishedStories();\n  const items: MetadataRoute.Sitemap = [\n    { url: absUrl(\"/\"), lastModified: stories[0]?.updatedAt },\n    ...SECTIONS.map((section) => ({ url: absUrl(`/${section}/`), lastModified: stories.find((s) => s.section === section)?.updatedAt })),\n    ...SIGNS.map((sign) => ({ url: absUrl(`/horoscope/${sign}/`), lastModified: getDailySign(sign)?.updatedAt })),\n    ...stories.map((s) => ({ url: absUrl(storyPath(s)), lastModified: s.updatedAt })),\n  ];\n  void SITE_ORIGIN; void allPublicStoryParams;\n  return items;\n}\n""")
w("app/robots.ts", """import type { MetadataRoute } from \"next\";\nimport { SITE_ORIGIN } from \"@/lib/site\";\nexport default function robots(): MetadataRoute.Robots {\n  return { rules: [{ userAgent: \"*\", allow: \"/\", disallow: [\"/api/\", \"/preview\", \"/draft\"] }], sitemap: `${SITE_ORIGIN}/sitemap.xml` };\n}\n""")
w("app/not-found.tsx", """export default function NotFound() {\n  return (<main className=\"mx-auto max-w-5xl px-4 py-16\"><h1 className=\"font-serif text-3xl\">Not found</h1><p className=\"mt-3 text-muted\">That page is not in the Drew's News allowlist.</p></main>);\n}\n""")
